use hs_loop::dshgoal::{GoalSession,Authority};use serde_json::json;
static ENV:std::sync::Mutex<()>=std::sync::Mutex::new(());
#[test]fn wrapup_is_the_exact_dsh_complete_instruction(){let mut s=GoalSession::default();let g=s.host_command("Verify files").unwrap();let id=g["goal"]["id"].as_str().unwrap().to_owned();s.admit_round().unwrap();let a=Authority::GoalRound{id:id.clone(),revision:1,round:1};s.call("update_goal",&json!({"goal_id":id,"revision":1,"action":"complete"}),a.clone()).unwrap();let actual=s.wrapup(&a).unwrap();let expected="<goal_complete>\nObjective: \"Verify files\"\nThe goal is marked complete and this autonomous run is ending. Write the closing message to the user now: state the outcome, summarize what was done and how it was verified, and point to the concrete results (files, commits, or other artifacts). Report only what earlier rounds and tool results in this session actually establish; when a detail is not in the session, say so instead of inventing it. Note anything the user should review or do next. Address the user directly. Do not call any more tools in this run; further work waits for the user's next instruction.\n</goal_complete>";assert_eq!(actual,expected);}
#[test]fn deferred_context_is_after_result_as_durable_user_message(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let mut w=hs_log::StreamWriter::create(d.path(),id).unwrap();w.append(hs_core::EventBuilder::new(hs_core::EventKind::ToolCall).payload(hs_core::Payload::Inline(serde_json::to_vec(&json!({"plugin":"update_goal","args":{"action":"complete"},"result":{"goal":{"phase":"complete"}},"deferred_context":"<goal_complete>durable closing notice</goal_complete>"})).unwrap()))).unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let a=hs_loop::assembler::assemble_messages(&r,&r.events().unwrap(),20000);assert_eq!(a.messages.len(),3);assert_eq!(a.messages[1]["role"],"tool");assert_eq!(a.messages[2],json!({"role":"user","content":"<goal_complete>durable closing notice</goal_complete>"}));}
#[test]fn blocked_wrapup_quotes_reason_and_does_not_repeat_in_tool_result(){let mut s=GoalSession::default();let g=s.host_command("Fix failure").unwrap();let id=g["goal"]["id"].as_str().unwrap().to_owned();for _ in 0..3{s.admit_round().unwrap();}let a=Authority::GoalRound{id:id.clone(),revision:1,round:3};let output=s.call("update_goal",&json!({"goal_id":id,"revision":1,"action":"blocked","blocked_reason":"Need \"key\"\nthen retry"}),a.clone()).unwrap();assert!(output.get("deferred_context").is_none());let note=s.wrapup(&a).unwrap();assert!(note.starts_with("<goal_blocked>\nObjective: \"Fix failure\"\nBlocked: \"Need \\\"key\\\"\\nthen retry\"\n"));assert!(s.wrapup(&Authority::HumanRoot).is_none());}
#[test]fn successful_autonomous_update_defers_exact_notice_on_next_model_request(){let _guard=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}let log=d.path().join("run");let mut session=hs_loop::repl::ReplSession::load(&cfg,&log,true,Some(2)).unwrap();let g=session.host_goal_command("Verify fixture").unwrap();std::fs::write(&script,format!("{}\n{}\n",json!({"tool":"update_goal","args":{"goal_id":g["goal"]["id"],"revision":1,"action":"complete"}}),json!({"tool":"get_goal","args":{}}))).unwrap();let result=session.run_next_goal_round().unwrap().unwrap();assert!(!result.passed,"goal state must not fabricate a checker pass");let r=hs_log::StreamReader::open(&log,session.stream_id()).unwrap();let events=r.events().unwrap();let payloads:Vec<serde_json::Value>=events.iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let mirror=payloads.iter().find(|v|v["plugin"]=="update_goal"&&v["record_type"]=="mirror").expect("durable tool mirror");let notice=mirror["deferred_context"].as_str().expect("deferred notice");assert!(notice.starts_with("<goal_complete>\nObjective: \"Verify fixture\"\n"));let calls:Vec<_>=payloads.iter().filter_map(|v|v["messages"].as_array()).collect();assert!(calls.iter().any(|m|m.windows(2).any(|p|p[0]["role"]=="tool"&&p[1]["role"]=="user"&&p[1]["content"]==notice)));assert_eq!(payloads.iter().filter(|v|v["deferred_context"].is_string()).count(),1);}
#[test]fn compacted_notice_remains_in_distiller_source(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let mut w=hs_log::StreamWriter::create(d.path(),id).unwrap();w.append(hs_core::EventBuilder::new(hs_core::EventKind::ToolCall).payload(hs_core::Payload::Inline(serde_json::to_vec(&json!({"plugin":"update_goal","args":{},"result":{},"deferred_context":"EXACT-DURABLE-CLOSING-NOTICE"})).unwrap()))).unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let a=hs_loop::assembler::assemble_messages(&r,&r.events().unwrap(),1);assert!(a.compressed.unwrap().lines[0].contains("EXACT-DURABLE-CLOSING-NOTICE"));}

#[test]fn feedback_off_autonomous_update_defers_exact_notice_on_next_model_request(){let _guard=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}let log=d.path().join("run");let mut session=hs_loop::repl::ReplSession::load(&cfg,&log,false,Some(2)).unwrap();let g=session.host_goal_command("Verify fixture").unwrap();std::fs::write(&script,format!("{}\n{}\n",json!({"tool":"update_goal","args":{"goal_id":g["goal"]["id"],"revision":1,"action":"complete"}}),json!({"tool":"get_goal","args":{}}))).unwrap();let result=session.run_next_goal_round().unwrap().unwrap();assert!(!result.passed,"goal state must not fabricate a checker pass");let r=hs_log::StreamReader::open(&log,session.stream_id()).unwrap();let events=r.events().unwrap();let payloads:Vec<serde_json::Value>=events.iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let mirror=payloads.iter().find(|v|v["plugin"]=="update_goal"&&v["record_type"]=="mirror").expect("durable tool mirror");let notice=mirror["deferred_context"].as_str().expect("deferred notice");assert!(notice.starts_with("<goal_complete>\nObjective: \"Verify fixture\"\n"));let calls:Vec<_>=payloads.iter().filter_map(|v|v["messages"].as_array()).collect();assert!(calls.iter().any(|m|m.windows(2).any(|p|p[0]["role"]=="tool"&&p[1]["role"]=="user"&&p[1]["content"]==notice)));assert_eq!(payloads.iter().filter(|v|v["deferred_context"].is_string()).count(),1);}